CREATE TABLE coupon_definition (id BIGINT NOT NULL AUTO_INCREMENT,campaign_id BIGINT NOT NULL,code VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(160) NOT NULL,discount_type VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,fixed_minor BIGINT NULL,percentage_bps INT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,minimum_minor BIGINT NOT NULL DEFAULT 0,total_stock BIGINT NOT NULL,claimed_stock BIGINT NOT NULL DEFAULT 0,per_user_limit INT NOT NULL DEFAULT 1,game_id BIGINT NULL,edition_id BIGINT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_coupon_definition_code UNIQUE(code),KEY idx_coupon_definition_campaign(campaign_id,id DESC),KEY idx_coupon_definition_game(game_id,id DESC),KEY idx_coupon_definition_edition(edition_id),CONSTRAINT ck_coupon_definition_code CHECK(REGEXP_LIKE(code,'^[A-Z0-9-]{3,32}$','c')),CONSTRAINT ck_coupon_definition_currency CHECK(REGEXP_LIKE(currency,'^[A-Z]{3}$','c')),CONSTRAINT ck_coupon_definition_discount CHECK((discount_type='fixed' AND fixed_minor>0 AND percentage_bps IS NULL) OR (discount_type='percentage' AND fixed_minor IS NULL AND percentage_bps BETWEEN 1 AND 10000)),CONSTRAINT ck_coupon_definition_minimum CHECK(minimum_minor>=0),CONSTRAINT ck_coupon_definition_stock CHECK(total_stock>0 AND claimed_stock BETWEEN 0 AND total_stock),CONSTRAINT ck_coupon_definition_limit CHECK(per_user_limit>0),CONSTRAINT ck_coupon_definition_scope CHECK(edition_id IS NULL OR game_id IS NOT NULL),CONSTRAINT fk_coupon_definition_campaign FOREIGN KEY(campaign_id) REFERENCES coupon_campaign(id) ON DELETE RESTRICT,CONSTRAINT fk_coupon_definition_game FOREIGN KEY(game_id) REFERENCES game(id) ON DELETE RESTRICT,CONSTRAINT fk_coupon_definition_edition FOREIGN KEY(edition_id) REFERENCES game_edition(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
